-- Lot 211 : payloads 301 a 330 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-198","moteur":"chatgpt","payload":"[RaccourcIA — /productcarousel]\n\nMISSION\nCréer une série de slides produit cohérentes et convertissantes. Produis par défaut quatre images séparées: couverture, usage, détail, CTA. Garde dimensions, produit, palette et typo constants; n’invente pas de preuve pour remplir une page.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « message » ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Carrousel produit » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Produis par défaut quatre images séparées: couverture, usage, détail, CTA. Garde dimensions, produit, palette et typo constants; n’invente pas de preuve pour remplir une page. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"f93ca3ac843a21a066a259c375e64d9dbed0ebf21dcb85ac50ba0c087cc07f24"},{"ref":"RCI-IMG-198","moteur":"claude","payload":"[RaccourcIA — /productcarousel]\n\nMISSION\nCréer une série de slides produit cohérentes et convertissantes. Produis par défaut quatre images séparées: couverture, usage, détail, CTA. Garde dimensions, produit, palette et typo constants; n’invente pas de preuve pour remplir une page.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « message » ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Carrousel produit » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Produis par défaut quatre images séparées: couverture, usage, détail, CTA. Garde dimensions, produit, palette et typo constants; n’invente pas de preuve pour remplir